-- Seed data for orders table. Fields match app.models.order.Order.
ON DUPLICATE KEY UPDATE user_id=VALUES(user_id), platform=VALUES(platform), country=VALUES(country), currency=VALUES(currency), total_amount=VALUES(total_amount), payment_status=VALUES(payment_status), fulfillment_status=VALUES(fulfillment_status), logistics_status=VALUES(logistics_status), shipped_at=VALUES(shipped_at), delivered_at=VALUES(delivered_at);